            "content": {
              "version": "KqlItem/1.0",
              "query": "resources\r\n| where type =~ 'microsoft.web/sites'\r\n| mv-expand ssl = properties.hostNameSslStates\r\n| extend sslState = tostring(ssl.sslState), hostName = tostring(ssl.name), thumbprint = tostring(ssl.thumbprint)\r\n| where sslState != 'Disabled' and isnotempty(thumbprint)\r\n| project siteId = id, siteName = name, hostName, sslState, thumbprint, kind, resourceGroup, subscriptionId\r\n| join kind=leftouter (\r\n    resources\r\n    | where type =~ 'microsoft.web/certificates'\r\n    | extend ExpirationDate = todatetime(properties.expirationDate)\r\n    | extend DaysRemaining = datetime_diff('day', ExpirationDate, now())\r\n    | extend ExpiryStatus = case(\r\n        isnull(ExpirationDate), 'Unknown',\r\n        DaysRemaining < 0, 'Expired',\r\n        DaysRemaining <= 30, 'Critical (< 30 Days)',\r\n        DaysRemaining <= 60, 'Warning (31 - 60 Days)',\r\n        DaysRemaining <= 90, 'Attention (61 - 90 Days)',\r\n        'Healthy (> 90 Days)'\r\n    )\r\n    | extend ExpiryFilterKey = case(\r\n        isnull(ExpirationDate), 'Unknown',\r\n        DaysRemaining < 0, 'Expired',\r\n        DaysRemaining <= 30, 'Critical',\r\n        DaysRemaining <= 60, 'Warning',\r\n        DaysRemaining <= 90, 'Attention',\r\n        'Healthy'\r\n    )\r\n    | extend Subject = tostring(properties.subjectName)\r\n    | extend Issuer = tostring(properties.issuer)\r\n    | extend thumbprint = tostring(properties.thumbprint)\r\n    | project certId = id, certName = name, Subject, Issuer, ExpirationDate, DaysRemaining, ExpiryStatus, ExpiryFilterKey, thumbprint\r\n) on thumbprint\r\n| where '{ExpiryThreshold}' == 'all' or isempty(ExpiryFilterKey) or ExpiryFilterKey == '{ExpiryThreshold}'\r\n| project AppService = siteId, HostName = hostName, SSLState = sslState, Certificate = certId, Subject, Issuer, ExpirationDate, DaysRemaining, ExpiryStatus, Thumbprint = thumbprint, Kind = kind, resourceGroup, subscriptionId\r\n| sort by DaysRemaining asc",
