        "items": [
          {
            "type": 1,
            "content": {
              "json": "### Application Gateways SSL Certificates (`microsoft.network/applicationgateways`)\r\nIdentifies SSL listeners and whether certificates are integrated with **Azure Key Vault for automated rotation** vs **manual file uploads**."
            },
            "name": "text - App Gateway Intro"
