          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "resources\r\n| where type =~ 'microsoft.network/applicationgateways'\r\n| mv-expand cert = properties.sslCertificates\r\n| extend certName = tostring(cert.name)\r\n| extend keyVaultSecretId = tostring(cert.properties.keyVaultSecretId)\r\n| extend certProvisioningState = tostring(cert.properties.provisioningState)\r\n| extend KeyVaultIntegration = iff(isnotempty(keyVaultSecretId), 'Integrated with Key Vault', 'Manual Upload (Risk of Expiration)')\r\n| extend AutoRotation = iff(isnotempty(keyVaultSecretId) and keyVaultSecretId !matches regex @'/[0-9a-f]{32}$', 'Auto-Rotate (Unversioned URI)', iff(isnotempty(keyVaultSecretId), 'Pinned Version (Manual Update Req)', 'None (Embedded Cert)'))\r\n| project ApplicationGateway = id, CertificateName = certName, KeyVaultIntegration, AutoRotation, KeyVaultSecretURI = keyVaultSecretId, ProvisioningState = certProvisioningState, location, resourceGroup, subscriptionId\r\n| sort by KeyVaultIntegration asc, CertificateName asc",
              "size": 2,
              "title": "Application Gateway SSL Certificates & Auto-Rotation Status (Live ARG)",
              "noDataMessage": "No Application Gateways found in selected subscriptions.",
              "showExportToExcel": true,
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
